const ThumbsUpIcon: React.FC<{ size: number; color: string }> = ({ size, color }) => (
  <svg 
    xmlns="http://www.w3.org/2000/svg" 
    width={size} 
    height={size} 
    viewBox="0 0 24 24" 
    fill="none" 
    stroke={color} 
    strokeWidth="1.5" 
    strokeLinecap="round" 
    strokeLinejoin="round"
  >
    <path d="M7 10v12" />
    <path d="M15 5.88 14 10h5.83a2 2 0 0 1 1.92 2.56l-2.33 8A2 2 0 0 1 17.5 22H4a2 2 0 0 1-2-2v-8a2 2 0 0 1 2-2h2.76a2 2 0 0 0 1.79-1.11L12 2h0a3.13 3.13 0 0 1 3 3.88Z" />
  </svg>
);

const RocketSequence: React.FC<RocketSequenceProps> = ({
  backgroundColor = "#FF4D4D",
  transparentBackground = false,
  durationInSeconds = 5,
  iconColor = "#FFFFFF",
  iconSize = 350,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings based on duration
  const totalFrames = Math.max(1, durationInSeconds) * fps;
  const idleStartFrame = Math.floor(totalFrames * 0.15);
  const launchStartFrame = Math.floor(totalFrames * 0.35);
  const launchEndFrame = Math.floor(totalFrames * 0.55);
  const thumbsUpStartFrame = Math.floor(totalFrames * 0.6);

  // === ROCKET ANIMATION LOGIC ===
  
  // 1. Entrance scale
  const rocketScale = spring({
    fps,
    frame,
    config: { damping: 12, stiffness: 100 },
  });

  // 2. Shake effect while idling
  const isShaking = frame >= idleStartFrame && frame < launchEndFrame;
  const shakeIntensity = iconSize * 0.03;
  const shakeX = isShaking ? Math.sin((frame - idleStartFrame) * 1.5) * shakeIntensity : 0;
  const shakeY = isShaking ? Math.cos((frame - idleStartFrame) * 2) * shakeIntensity : 0;

  // 3. Takeoff flight path (moves up and right, following its nose)
  const takeoffX = interpolate(
    frame,
    [launchStartFrame, launchEndFrame],
    [0, width],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.in(Easing.quad) }
  );
  
  const takeoffY = interpolate(
    frame,
    [launchStartFrame, launchEndFrame],
    [0, -height],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.in(Easing.quad) }
  );

  const rocketTransform = `translate(${shakeX + takeoffX}px, ${shakeY + takeoffY}px) scale(${rocketScale})`;
  const rocketOpacity = frame > launchEndFrame ? 0 : 1;

  // === THUMBS UP ANIMATION LOGIC ===
  
  // 1. Entrance scale
  const thumbsUpScale = spring({
    fps,
    frame: frame - thumbsUpStartFrame,
    config: { damping: 10, stiffness: 80 },
  });

  // 2. Rotational spring for playful entrance
  const thumbsUpRotateSpring = spring({
    fps,
    frame: frame - thumbsUpStartFrame,
    config: { damping: 12, stiffness: 90 },
  });
  
  const thumbsUpRotate = interpolate(thumbsUpRotateSpring, [0, 1], [-25, 0]);
  const thumbsUpTransform = `scale(${thumbsUpScale}) rotate(${thumbsUpRotate}deg)`;

  return (
    <AbsoluteFill 
      style={{ 
        backgroundColor: bgColor, 
        justifyContent: "center", 
        alignItems: "center",
        transition: "none"
      }}
    >
      {/* Rocket Container */}
      {frame < launchEndFrame + fps && (
        <div 
          style={{
            position: "absolute",
            transform: rocketTransform,
            opacity: rocketOpacity,
            transition: "none",
            display: "flex",
            justifyContent: "center",
            alignItems: "center"
          }}
        >
          <RocketIcon size={iconSize} color={iconColor} />
        </div>
      )}

      {/* Thumbs Up Container */}
      {frame >= thumbsUpStartFrame && (
        <div 
          style={{
            position: "absolute",
            transform: thumbsUpTransform,
            transition: "none",
            display: "flex",
            justifyContent: "center",
            alignItems: "center"
          }}
        >
          <ThumbsUpIcon size={iconSize} color={iconColor} />
        </div>
      )}
    </AbsoluteFill>
  );
};

export default RocketSequence;